def quantities(lines):
    if not isinstance(lines, list):
        raise ValueError('lines must be a list')
    totals = {}
    for line in lines:
        if not isinstance(line, dict):
            raise ValueError('invalid line')
        sku, count = line.get('sku'), line.get('quantity')
        if not isinstance(sku, str) or not sku or type(count) is not int or count <= 0:
            raise ValueError('invalid line')
        totals[sku] = totals.get(sku, 0) + count
    return totals

