from .lines import quantities

def reserve(inventory, lines):
    if not isinstance(inventory, dict):
        raise ValueError('inventory must be a dictionary')
    for sku, count in inventory.items():
        if not isinstance(sku, str) or not sku or type(count) is not int or count < 0:
            raise ValueError('invalid inventory')
    requested = quantities(lines)
    result = dict(inventory)
    for sku, count in requested.items():
        if sku not in result or count > result[sku]:
            raise ValueError('insufficient inventory')
        result[sku] -= count
    return result

