def replace_spans(text, changes):
    if not isinstance(text, str) or not isinstance(changes, list):
        raise ValueError('invalid text or changes')
    spans = []
    for change in changes:
        if not isinstance(change, dict):
            raise ValueError('invalid change')
        start, end, value = change.get('start'), change.get('end'), change.get('text')
        if (type(start) is not int or type(end) is not int or
                not 0 <= start < end <= len(text) or not isinstance(value, str)):
            raise ValueError('invalid change')
        spans.append((start, end, value))
    spans.sort()
    result, cursor = [], 0
    for start, end, value in spans:
        if start < cursor:
            raise ValueError('overlapping changes')
        result.extend((text[cursor:start], value))
        cursor = end
    result.append(text[cursor:])
    return ''.join(result)

