from .core import replace_spans

def apply_documents(documents, edits):
    if not isinstance(documents, dict) or not isinstance(edits, dict):
        raise ValueError('invalid documents or edits')
    if any(not isinstance(k, str) or not isinstance(v, str) for k, v in documents.items()):
        raise ValueError('invalid document')
    for name in edits:
        if not isinstance(name, str):
            raise ValueError('invalid filename')
        if name not in documents:
            raise KeyError(name)
    result = dict(documents)
    for name, changes in edits.items():
        result[name] = replace_spans(documents[name], changes)
    return result

