from .versions import parse_version

def choose(records, include_rc=False):
    if not isinstance(records, list) or type(include_rc) is not bool:
        raise ValueError('invalid catalog')
    selected, best = None, None
    for row in records:
        if not isinstance(row, dict) or type(row.get('yanked', False)) is not bool:
            raise ValueError('invalid record')
        major, minor, patch, rc = parse_version(row.get('version'))
        if row.get('yanked', False) or (rc is not None and not include_rc):
            continue
        key = (major, minor, patch, rc is None, rc if rc is not None else 0)
        if best is None or key > best:
            selected, best = row, key
    return dict(selected) if selected is not None else None

