from copy import deepcopy
from .indexing import index_rows

def left_join(left, right, key):
    index_rows(left, key)
    index = index_rows(right, key)
    result = []
    for row in left:
        for match in index.get(row[key], [None]):
            result.append({'left':deepcopy(row), 'right':deepcopy(match)})
    return result
